48:TunnelIPv6Interface::TunnelIPv6Interface(const std::string& interface_name, int mtu):
49:#if FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION
50:     UnixSocket(open("/dev/null",O_RDWR), true),
51:#else
52:     UnixSocket(tunnel_open(interface_name.c_str()), true),
53:#endif
54:     mInterfaceName(interface_name),
55:     mLastError(0),
56:     mNetlinkFD(-1),
57:#if FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION
58:     mNetifMgmtFD(-1),
59:#else
60:     mNetifMgmtFD(netif_mgmt_open()),
61:#endif
62:     mIsRunning(false),
63:     mIsUp(false)
64:{
65:     if (0 > mFDRead) {
66:             throw std::invalid_argument("Unable to open tunnel interface");
67:     }
68:
69:#if !FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION
70:     {
71:             char ActualInterfaceName[TUNNEL_MAX_INTERFACE_NAME_LEN] = "";
72:             int ret = 0;
73:             ret = tunnel_get_name(mFDRead, ActualInterfaceName, sizeof(ActualInterfaceName));
74:             if (ret) {
75:                     syslog(LOG_WARNING,
76:                                "TunnelIPv6Interface: Couldn't get tunnel name! errno=%d, %s",
77:                                errno,
78:                                strerror(errno));
79:             } else if (mInterfaceName != ActualInterfaceName) {
80:                     syslog(LOG_WARNING,
81:                                "TunnelIPv6Interface: Couldn't create tunnel named \"%s\", got \"%s\" instead!",
82:                                mInterfaceName.c_str(),
83:                                ActualInterfaceName);
84:                     mInterfaceName = ActualInterfaceName;
85:             }
86:     }
87:
88:     netif_mgmt_set_mtu(mNetifMgmtFD, mInterfaceName.c_str(), mtu);
89:
90:     setup_signals();
91:#endif
92:}
